import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target = inputs["target_positions"].copy()
    events = inputs["position_events"].copy()

    # 1. distinct by batch_seq (same event delivered more than once -> apply once)
    events = events.drop_duplicates(subset=["batch_seq"], keep="first")

    # Build lookup of current state per key from target_positions
    target_state = {}
    for _, row in target.iterrows():
        key = (row["account_id"], row["symbol"])
        target_state[key] = {
            "qty": row["qty"],
            "price": row["price"],
            "row_version": row["row_version"],
        }

    final_state = dict(target_state)  # will be mutated as we apply events
    closed_rows = []

    if len(events) > 0:
        grouped = events.groupby(["account_id", "symbol"], sort=False)
    else:
        grouped = []

    for key, grp in (grouped if len(events) > 0 else []):
        account_id, symbol = key
        existing = target_state.get(key)

        # 2. Replay guard: only applies when a target row exists for the key
        if existing is not None:
            guard_version = existing["row_version"]
            grp = grp[grp["row_version"] > guard_version]

        # 3. Apply remaining events in order
        grp = grp.sort_values(["row_version", "batch_seq"], kind="mergesort")

        state = dict(existing) if existing is not None else None
        last_event_closed = False
        last_event_version = None

        for _, ev in grp.iterrows():
            op = ev["op"]
            qty = ev["qty"]
            price = ev["price"]
            rv = ev["row_version"]

            acted_removed = False

            if op == "D":
                if state is not None:
                    state = None
                    acted_removed = True
                # else: does nothing
            elif op in ("I", "U"):
                if (not pd.isna(qty)) and qty == 0:
                    # zero-quantity close
                    if state is not None:
                        state = None
                        acted_removed = True
                    # else: does nothing
                else:
                    if state is not None:
                        if op == "U" and pd.isna(price):
                            new_price = state["price"]
                        else:
                            new_price = price
                        state = {
                            "qty": qty,
                            "price": new_price,
                            "row_version": rv,
                        }
                    else:
                        # created fresh: price NULL stays NULL regardless of I/U
                        state = {
                            "qty": qty,
                            "price": price,
                            "row_version": rv,
                        }
            # record outcome of THIS event only (overwrite previous outcome)
            last_event_closed = acted_removed
            if acted_removed:
                last_event_version = rv

        if state is None:
            final_state.pop(key, None)
        else:
            final_state[key] = state

        if last_event_closed:
            closed_rows.append(
                {
                    "account_id": account_id,
                    "symbol": symbol,
                    "closed_version": last_event_version,
                }
            )

    # Build new_positions
    new_rows = []
    for key, state in final_state.items():
        qty_val = state["qty"]
        try:
            qty_val = int(qty_val)
        except (TypeError, ValueError):
            pass
        new_rows.append(
            {
                "account_id": key[0],
                "symbol": key[1],
                "qty": qty_val,
                "price": state["price"],
                "row_version": int(state["row_version"]),
            }
        )

    new_positions = pd.DataFrame(
        new_rows, columns=["account_id", "symbol", "qty", "price", "row_version"]
    )
    if len(new_positions) > 0:
        new_positions = new_positions.sort_values(
            ["account_id", "symbol"], kind="mergesort"
        ).reset_index(drop=True)
        new_positions["account_id"] = new_positions["account_id"].astype("int64")
        new_positions["qty"] = new_positions["qty"].astype("int64")
        new_positions["price"] = new_positions["price"].astype("float64")
        new_positions["row_version"] = new_positions["row_version"].astype("int64")
    else:
        new_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "qty": pd.Series(dtype="int64"),
                "price": pd.Series(dtype="float64"),
                "row_version": pd.Series(dtype="int64"),
            }
        )

    closed_positions = pd.DataFrame(
        closed_rows, columns=["account_id", "symbol", "closed_version"]
    )
    if len(closed_positions) > 0:
        closed_positions = closed_positions.sort_values(
            ["account_id", "symbol"], kind="mergesort"
        ).reset_index(drop=True)
        closed_positions["account_id"] = closed_positions["account_id"].astype("int64")
        closed_positions["closed_version"] = closed_positions["closed_version"].astype(
            "int64"
        )
    else:
        closed_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "closed_version": pd.Series(dtype="int64"),
            }
        )

    return {"new_positions": new_positions, "closed_positions": closed_positions}
